#!/usr/bin/env python3
"""Patch 49: brief overview tiles (what the case is, what happened), the sidebar's outcome symbol
on each tile, no fit rings in the sidebar, and its counts aligned. Frontend only. Requires patch
48. Run from the repository root. Checked against the exact files it was written for; nothing is
written unless all of it matches. Safe to re-run."""
import hashlib, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
REPLACE = {'frontend/src/CaseSwitcher.jsx': {'before': 'c0a16bdf4167887bf1a3128072e1dc9329b4c143e03e8a8fc86a79eb4102f717', 'after': 'import { useLayoutEffect, useRef, useState } from \'react\';\nimport { FAMILY_LABEL, FAMILY_SHORT } from \'./families\';\nimport OutcomeIcon from \'./OutcomeIcon\';\nimport \'./caseSwitcher.css\';\n\n/**\n * The case list as a macOS source list: grouped by family (what kind of test a\n * case is), each group collapsible; every row shows the system\'s own outcome -\n * a vessel named, or an abstention - the vessel it named and its fit, from the\n * same /api/overview fields as the overview grid. One selection travels to the\n * active row. The family never says which vessel did it; the outcome is the\n * system\'s, right or wrong.\n */\nconst FAMILY_ICON = {\n  decoy: <><circle cx="6" cy="8" r="3.2" /><circle cx="11" cy="8" r="3.2" strokeDasharray="1.6 1.4" /></>,\n  moving_discharge: <><path d="M2.5 8h9" /><path d="M9 5l3 3-3 3" /><path d="M2.5 11.5q1.5-1 3 0t3 0" /></>,\n  absent_source: <circle cx="8" cy="8" r="5" strokeDasharray="2 1.8" />,\n  crowded: <><circle cx="5" cy="5.5" r="1.4" /><circle cx="10.5" cy="5" r="1.4" /><circle cx="7.5" cy="10.5" r="1.4" /><circle cx="12" cy="10" r="1.4" /><circle cx="4" cy="10.5" r="1.4" /></>,\n  along_track_ribbon: <path d="M2 10q2-5 4 0t4 0 4-3" />,\n};\n\nexport default function CaseSwitcher({ incidents, active, onSelect, summaries = {} }) {\n  const wrapRef = useRef(null);\n  const rowRefs = useRef({});\n  const [box, setBox] = useState(null);\n  const [ready, setReady] = useState(false);\n  const [closed, setClosed] = useState({});\n\n  useLayoutEffect(() => {\n    const measure = () => {\n      const row = rowRefs.current[active];\n      // no active row - on the overview, or inside a collapsed group: no selection\n      if (!row || !wrapRef.current || row.closest(\'.sl-group.is-closed\')) { setBox(null); return; }\n      setBox({ y: row.getBoundingClientRect().top - wrapRef.current.getBoundingClientRect().top, h: row.offsetHeight });\n    };\n    measure();\n    const id = requestAnimationFrame(() => setReady(true));\n    const ro = typeof ResizeObserver !== \'undefined\' ? new ResizeObserver(measure) : null;\n    if (ro && wrapRef.current) ro.observe(wrapRef.current);\n    // groups animate their height: measure again when that animation ends\n    const wrap = wrapRef.current;\n    wrap?.addEventListener(\'transitionend\', measure);\n    return () => { cancelAnimationFrame(id); ro?.disconnect(); wrap?.removeEventListener(\'transitionend\', measure); };\n  }, [active, incidents, closed]);\n\n  if (!incidents?.length) return null;\n  const groups = [];\n  for (const c of incidents) {\n    let g = groups.find((x) => x.family === c.family);\n    if (!g) { g = { family: c.family, cases: [] }; groups.push(g); }\n    g.cases.push(c);\n  }\n\n  return (\n    <nav className="case-switcher sl" aria-label="Incident cases">\n      <div className="sl-section"><span>Cases</span><span className="sl-count">{incidents.length}</span></div>\n      <div className="case-list-wrap sl-wrap" ref={wrapRef}>\n        <span className={`case-highlight${ready && box ? \' is-ready\' : \'\'}`}\n              style={box ? { \'--y\': `${box.y}px`, \'--h\': `${box.h}px` } : undefined} aria-hidden="true" />\n        {groups.map((g) => {\n          const isClosed = !!closed[g.family];\n          return (\n            <div key={g.family} className={`sl-group${isClosed ? \' is-closed\' : \'\'}`}>\n              <button type="button" className="sl-group-head" aria-expanded={!isClosed}\n                      onClick={() => setClosed((s) => ({ ...s, [g.family]: !s[g.family] }))} title={FAMILY_LABEL[g.family] ?? g.family}>\n                <svg className="sl-fam" viewBox="0 0 16 16" aria-hidden="true">{FAMILY_ICON[g.family] ?? <circle cx="8" cy="8" r="4" />}</svg>\n                <span className="sl-group-name">{FAMILY_SHORT[g.family] ?? g.family}</span>\n                {/* the chevron sits just before the count, so every count shares one right edge */}\n                <span className="sl-chev" aria-hidden="true" />\n                <span className="sl-count">{g.cases.length}</span>\n              </button>\n              <div className="sl-rows"><ul className="case-list">\n                {g.cases.map((c) => {\n                  const f = summaries[c.incident_id];\n                  const unknown = f ? f.unknown_source : c.outcome === \'unknown_source\';\n                  const isActive = c.incident_id === active;\n                  return (\n                    <li key={c.incident_id}>\n                      <button ref={(el) => { rowRefs.current[c.incident_id] = el; }} type="button"\n                              className={`case-item sl-row${isActive ? \' is-active\' : \'\'}`} aria-current={isActive ? \'true\' : undefined}\n                              onClick={() => onSelect(c.incident_id)}>\n                        <OutcomeIcon abstain={unknown} />\n                        <span className="case-text">\n                          <span className="case-id">{c.incident_id.replace(\'case_\', \'Case \')}</span>\n                          <span className="case-description">{f ? (unknown ? \'No vessel named\' : f.best?.vessel_key) : (FAMILY_LABEL[c.family] ?? c.family)}</span>\n                        </span>\n                        <span className="visually-hidden">{unknown ? \', outcome: no vessel named\' : \', outcome: a vessel named\'}</span>\n                      </button>\n                    </li>\n                  );\n                })}\n              </ul></div>\n            </div>\n          );\n        })}\n      </div>\n      <div className="sl-legend" aria-hidden="true">\n        <span><i className="sl-outcome is-named"><svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="6" /><path d="M5.2 8.2l2 2 3.8-4.2" /></svg></i>vessel named</span>\n        <span><i className="sl-outcome is-abstain"><svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="6" /><path d="M4 12L12 4" /></svg></i>abstains</span>\n      </div>\n    </nav>\n  );\n}\n'}, 'frontend/src/Overview.jsx': {'before': 'b019247eadeba605d1c3663350acbfdb4e9f3806a8a583122ef011dc08ccaec0', 'after': 'import { useEffect, useState } from \'react\';\nimport { FAMILY_LABEL, FAMILY_SCENARIO } from \'./families\';\nimport OutcomeIcon from \'./OutcomeIcon\';\nimport \'./overview.css\';\n\n/**\n * Mission control: every case at a glance. Each tile\'s finding is produced by\n * the same rule as the Case Finding card (findingText.js) from the fields\n * /api/overview copies out of each case\'s artifacts - nothing is summarised or\n * written here. The family says what kind of test a case is, never which vessel\n * did it; the status dot is the system\'s own outcome.\n */\n/** What actually happened, in one sentence, from the case\'s result. */\nfunction happened(f, differs) {\n  if (!f) return \'Not yet analysed.\';\n  if (f.unknown_source) return \'No vessel named — no candidate fit the slick well enough.\';\n  const lead = f.best?.vessel_key;\n  return differs ? `Forward replay named ${lead}; the nearest vessel, ${f.nearest.vessel_key}, wasn’t supported.`\n    : `Forward replay named ${lead}, which was also the nearest vessel.`;\n}\n\nexport default function Overview({ api, onOpen, family = \'all\', chips = null }) {\n  const [rows, setRows] = useState(null);\n  const [error, setError] = useState(null);\n  useEffect(() => {\n    let live = true;\n    api.overview().then((r) => live && setRows(r)).catch((e) => live && setError(String(e.message ?? e)));\n    return () => { live = false; };\n  }, [api]);\n\n  if (error) return <div className="ov"><div className="error-banner">Failed to load the case overview: {error}</div></div>;\n  if (!rows) return <div className="ov"><div className="ov-loading">Loading cases…</div></div>;\n\n  const shown = family === \'all\' ? rows : rows.filter((r) => r.family === family);\n  const named = shown.filter((r) => r.finding && !r.finding.unknown_source).length;\n  const abstained = shown.filter((r) => r.finding?.unknown_source).length;\n  return (\n    <div className="ov">\n      <header className="ov-head">\n        <h1>All cases</h1>\n        <p>{shown.length === rows.length ? `${rows.length} cases` : `${shown.length} of ${rows.length} cases`} · {named} {named === 1 ? \'names\' : \'name\'} a vessel · {abstained} {abstained === 1 ? \'abstains\' : \'abstain\'}</p>\n      </header>\n      {chips}\n      <div className="ov-grid">\n        {shown.map((r, i) => {\n          const f = r.finding;\n          const unknown = f?.unknown_source;\n          const differs = f && !unknown && f.nearest && f.best && f.nearest.vessel_key !== f.best.vessel_key;\n          return (\n            <button type="button" key={r.incident_id} className={`ov-tile${unknown ? \' is-abstain\' : \'\'}`}\n                    style={{ \'--k\': i }} onClick={() => onOpen(r.incident_id)}>\n              <span className="ov-top">\n                {f && <OutcomeIcon abstain={unknown} />}\n                <span className="ov-id">{r.incident_id.replace(\'case_\', \'Case \')}</span>\n              </span>\n              {/* what the case is, then what actually happened - nothing else */}\n              <span className="ov-scenario">{FAMILY_SCENARIO[r.family] ?? FAMILY_LABEL[r.family] ?? \'\'}</span>\n              <span className={`ov-happened${unknown ? \' is-abstain\' : \'\'}`}>{happened(f, differs)}</span>\n              <span className="ov-open">Open case →</span>\n            </button>\n          );\n        })}\n      </div>\n      <p className="ov-foot">Findings are physical consistency under tested assumptions: investigative leads, not proof of\n        responsibility. Every case is synthetic.</p>\n    </div>\n  );\n}\n'}, 'frontend/src/caseSwitcher.css': {'before': '27a9ad01dc7fa08ec10c430f302328f64d7700ab48a8efd516001ac2591cf1d4', 'after': '/* The case list as a macOS source list. */\n.sl { display: flex; flex-direction: column; }\n.sl-section { display: flex; justify-content: space-between; align-items: baseline; padding: 14px 10px 6px;\n              font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase;\n              letter-spacing: 0.07em; color: var(--label-3); }\n.sl-count { font-variant-numeric: tabular-nums; font-weight: var(--font-weight-medium); color: var(--label-3); letter-spacing: 0; }\n.sl-wrap { position: relative; }\n.sl-group { margin-bottom: 2px; }\n.sl-group-head { display: flex; align-items: center; gap: 7px; width: 100%; padding: 6px 10px 4px 6px; border: 0; background: transparent;\n                 cursor: default; font: inherit; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold);\n                 color: var(--label-2); border-radius: 7px; text-align: left; position: relative; z-index: 1; }\n.sl-group-head:hover { color: var(--label-1); background: var(--fill-hover); }\n.sl-group-head:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: -1px; }\n.sl-chev { width: 6px; height: 6px; margin: 0 2px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor;\n           transform: rotate(45deg) translate(-1px, -1px); transition: transform 260ms var(--ease-spring); opacity: 0.7; }\n.sl-group.is-closed .sl-chev { transform: rotate(-45deg); }\n.sl-fam { width: 15px; height: 15px; fill: none; stroke: var(--accent); stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }\n.sl-fam circle[r="1.4"] { fill: var(--accent); stroke: none; }\n.sl-group-name { flex: 1; }\n/* groups open and close by animating their height */\n.sl-rows { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 300ms cubic-bezier(0.22, 1, 0.36, 1), opacity 240ms ease; }\n.sl-rows > ul { min-height: 0; overflow: hidden; margin: 0; padding: 0; list-style: none; }\n.sl-group.is-closed .sl-rows { grid-template-rows: 0fr; opacity: 0; }\n\n.sl-row { display: flex; align-items: center; gap: 10px; width: 100%; padding: 7px 10px 7px 12px; }\n.sl-row .case-text { flex: 1; min-width: 0; display: flex; flex-direction: column; }\n.sl-row .case-id { font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); }\n.sl-row .case-description { font-family: var(--font-mono); font-size: 11px; opacity: 0.75; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.sl-outcome { flex: none; width: 17px; height: 17px; display: inline-grid; place-items: center; }\n.sl-outcome svg { width: 17px; height: 17px; fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.sl-outcome.is-named svg { stroke: var(--status-green); }\n.sl-outcome.is-named svg circle { fill: rgba(48, 209, 88, 0.14); }\n.sl-outcome.is-abstain svg { stroke: var(--status-orange); }\n.sl-outcome.is-abstain svg circle { fill: rgba(255, 159, 10, 0.14); }\n.sl-fit { flex: none; display: inline-flex; align-items: center; gap: 4px; font-family: var(--font-mono); font-size: 10.5px;\n          font-variant-numeric: tabular-nums; color: var(--label-2); }\n.sl-fit svg { width: 14px; height: 14px; }\n.sl-fit-track { fill: none; stroke: var(--fill-pressed); stroke-width: 2.2; }\n.sl-fit-arc { fill: none; stroke: #64d2ff; stroke-width: 2.2; stroke-linecap: round; }\n.sl-fit.is-below .sl-fit-arc { stroke: var(--status-orange); }\n/* on the selection, everything takes the selection\'s colour */\n.sl-row.is-active .case-description, .sl-row.is-active .sl-fit { color: inherit; opacity: 0.85; }\n.sl-row.is-active .sl-outcome svg { stroke: currentColor; }\n.sl-row.is-active .sl-outcome svg circle { fill: rgba(255, 255, 255, 0.2); }\n.sl-row.is-active .sl-fit-arc { stroke: #fff; }\n.sl-row.is-active .sl-fit-track { stroke: rgba(255, 255, 255, 0.3); }\n\n.sl-legend { display: flex; flex-wrap: wrap; gap: 6px 12px; margin-top: auto; padding: 16px 10px 4px; font-size: var(--font-size-xxs); color: var(--label-3); }\n.sl-legend span { display: inline-flex; align-items: center; gap: 5px; }\n.sl-legend .sl-outcome, .sl-legend .sl-outcome svg { width: 12px; height: 12px; }\n@media (prefers-reduced-motion: reduce) { .sl-rows, .sl-chev { transition: none; } }\n/* the sidebar lays out as a column so the legend sits at its foot */\n.finder-sidebar { display: flex; flex-direction: column; }\n.finder-sidebar > .sl { flex: 1; }\n\n/* the selection glides between rows on a gentle spring, with a soft glow */\n.case-highlight { box-shadow: 0 4px 14px rgba(10, 132, 255, 0.35), inset 0 0.5px 0 rgba(255, 255, 255, 0.25); }\n.case-highlight.is-ready { transition: transform 420ms cubic-bezier(0.34, 1.3, 0.64, 1), height 420ms cubic-bezier(0.34, 1.3, 0.64, 1), opacity 200ms ease; }\n.sl-row { transition: color 200ms ease, background-color 120ms ease, transform 160ms var(--ease-spring); }\n.sl-row:active { transform: scale(0.98); }\n.sl-row.is-active .case-id { font-weight: var(--font-weight-semibold); }\n@media (prefers-reduced-motion: reduce) {\n  .case-highlight.is-ready { transition: none; }\n  .finder-content, .finder-content > .finder-features, .finder-content > .finder-details { transition: none; animation: none; }\n  .finder-content.is-leaving { filter: none; transform: none; }\n  .finder-content.is-leaving::before { animation: none; opacity: 0; }\n}\n\n/* One symbol column and one text column down the whole sidebar: the Overview icon,\n   family symbols and outcome symbols share a 17 px column at 12 px; every label\n   starts 10 px after it. */\n.nav-overview { padding: 8px 10px 8px 12px; gap: 10px; }\n.nav-overview svg { width: 17px; height: 17px; }\n.sl-section { padding: 14px 10px 6px 12px; }\n.sl-group-head { gap: 10px; padding: 8px 10px 4px 12px; }\n.sl-fam { flex: none; width: 17px; height: 17px; }\n.sl-group-head .sl-count { margin-left: auto; }\n.sl-chev { flex: none; margin: 0 2px 0 2px; opacity: 0; transition: transform 260ms var(--ease-spring), opacity 160ms ease; }\n.sl-group-head:hover .sl-chev, .sl-group-head:focus-visible .sl-chev, .sl-group.is-closed .sl-chev { opacity: 0.7; }\n.sl-row { gap: 10px; padding: 7px 10px 7px 12px; }\n.sl-legend { padding: 16px 10px 4px 12px; }\n.nav-overview svg { flex: none; min-width: 17px; }\n\n/* every count - Cases and each group - on one right edge */\n.sl-section, .sl-group-head { padding-right: 12px; }\n.sl-count { min-width: 14px; text-align: right; }\n.sl-chev { margin: 0 4px 0 0; }\n'}, 'frontend/src/overview.css': {'before': '7671620dd53d5f1c87113c8f92390511fa0c4ba2a608ad15640931c8df37afc2', 'after': '/* Mission control: every case as a glass tile. */\n.ov { flex: 1; min-width: 0; height: 100%; overflow-y: auto; padding: var(--space-7) var(--space-7) var(--space-8); }\n.ov-head h1 { font-family: var(--font-display); font-size: 26px; font-weight: 700; letter-spacing: -0.02em; color: var(--label-1); }\n.ov-head p { margin: 4px 0 var(--space-6); font-size: var(--font-size-sm); color: var(--label-2); }\n.ov-loading { color: var(--label-2); font-size: var(--font-size-sm); }\n.ov-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; }\n.ov-tile {\n  position: relative; display: flex; flex-direction: column; gap: 10px; min-height: 176px; padding: 16px 16px 14px;\n  border: 0; border-radius: 14px; text-align: left; font: inherit; color: var(--label-1); cursor: default;\n  background: linear-gradient(160deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.015)), var(--surface-raised);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 6px 20px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.06);\n  --lift: 0px;\n  transform: perspective(900px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg)) translateY(var(--lift));\n  animation: ov-in 480ms var(--ease-spring) backwards; animation-delay: calc(var(--k) * 45ms);\n  transition: transform 700ms cubic-bezier(0.22, 1.2, 0.36, 1), box-shadow var(--dur-base) ease;\n}\n.ov-tile.is-tilting { transition: transform 160ms ease-out, box-shadow var(--dur-base) ease; }\n.ov-tile::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; opacity: 0;\n                  background: radial-gradient(360px circle at var(--mx, 50%) var(--my, 0%), rgba(var(--sheen-rgb), var(--sheen-max)), transparent 50%);\n                  transition: opacity 300ms ease; }\n.ov-tile.is-tilting::after { opacity: 1; }\n.ov-tile:hover { --lift: -3px; box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.55), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(10, 132, 255, 0.12); }\n.ov-tile:active { --lift: 1px; }\n.ov-tile:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 2px; }\n.ov-tile.is-abstain { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.55), 0 6px 20px rgba(0, 0, 0, 0.12); }\n.ov-tile.is-abstain:hover { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.8), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(255, 159, 10, 0.14); }\n.ov-top { display: flex; align-items: center; gap: 8px; }\n.ov-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--label-3); flex: none; }\n.ov-dot.is-named { background: var(--status-green); box-shadow: 0 0 8px rgba(48, 209, 88, 0.6); }\n.ov-dot.is-abstain { background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.6); }\n.ov-id { font-family: var(--font-mono); font-size: var(--font-size-sm); font-weight: var(--font-weight-semibold); }\n.ov-family { margin-left: auto; padding: 2px 8px; border-radius: 999px; font-size: var(--font-size-xxs); color: var(--label-2);\n             background: var(--fill-pressed); white-space: nowrap; }\n.ov-finding { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-1); }\n.ov-finding.is-pending { color: var(--label-3); }\n.ov-facts { font-size: var(--font-size-xs); color: var(--label-2); }\n.ov-facts b { color: var(--label-1); font-weight: var(--font-weight-semibold); }\n.ov-facts .mono, .ov-facts b.mono { font-family: var(--font-mono); }\n.ov-open { margin-top: auto; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); color: var(--accent);\n           opacity: 0; transform: translateX(-4px); transition: opacity var(--dur-base) ease, transform var(--dur-base) var(--ease-spring); }\n.ov-tile:hover .ov-open, .ov-tile:focus-visible .ov-open { opacity: 1; transform: none; }\n.ov-foot { margin-top: var(--space-6); font-size: var(--font-size-xs); color: var(--label-3); }\n@keyframes ov-in { from { opacity: 0; translate: 0 10px; } }\n@media (prefers-reduced-motion: reduce) { .ov-tile { animation: none; transform: none; } }\n\n/* the sidebar\'s way back to the overview */\n.nav-overview { display: flex; align-items: center; gap: 9px; width: 100%; margin: 0 0 10px; padding: 8px 12px;\n                border: 0; border-radius: 9px; background: transparent; color: var(--label-1); font: inherit;\n                font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); cursor: default; text-align: left; }\n.nav-overview:hover { background: var(--fill-hover); }\n.nav-overview.is-active { background: var(--accent); color: var(--on-accent); }\n.nav-overview svg { width: 15px; height: 15px; flex: none; }\n\n/* what the case is: its scenario, and the facts of the scene */\n.ov-scenario { font-size: var(--font-size-sm); line-height: 1.4; color: var(--label-1); font-weight: var(--font-weight-medium); }\n.ov-meta { font-size: var(--font-size-xs); color: var(--label-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }\n.ov-tile .ov-finding { color: var(--label-2); }\n\n/* tiles: the case, what it tests, and what happened */\n.ov-tile { min-height: 0; gap: 8px; padding: 16px 18px 18px; }\n.ov-top { gap: 9px; }\n.ov-top .sl-outcome, .ov-top .sl-outcome svg { width: 18px; height: 18px; }\n.ov-id { font-family: var(--font-display); font-size: var(--font-size-md); font-weight: var(--font-weight-semibold); letter-spacing: -0.01em; }\n.ov-scenario { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-1); font-weight: var(--font-weight-medium); }\n.ov-happened { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-2); padding-bottom: 14px; }\n.ov-happened.is-abstain { color: var(--status-orange); }\n.ov-open { position: absolute; right: 18px; bottom: 12px; margin: 0; }\n'}}
NEW = {'frontend/src/OutcomeIcon.jsx': '/** The outcome symbol, shared by the sidebar and the overview: a vessel named, or an abstention. */\nexport default function OutcomeIcon({ abstain, className = \'\' }) {\n  return (\n    <span className={`sl-outcome ${abstain ? \'is-abstain\' : \'is-named\'} ${className}`.trim()} aria-hidden="true">\n      <svg viewBox="0 0 16 16">\n        {abstain ? <><circle cx="8" cy="8" r="6" /><path d="M4 12L12 4" /></>\n          : <><circle cx="8" cy="8" r="6" /><path d="M5.2 8.2l2 2 3.8-4.2" /></>}\n      </svg>\n    </span>\n  );\n}\n'}
CL_OLD = 'vessels tracked and candidates replayed. The overview and benchmark endpoints stay available.\n'
CL_NEW = 'vessels tracked and candidates replayed. The overview and benchmark endpoints stay available.\n\n**A brief overview and a quieter sidebar.** Each overview tile now shows only the case, what it\ntests and one sentence on what happened, built from its result, with the same outcome symbol as\nthe sidebar (one shared component). The sidebar drops its fit rings, and every count sits on one\nright edge.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 48 entry this appends after was not found - apply patch 48 first")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 49: {len(writes)} files written, {skipped} already in place.")
